import { Component, For, JSX, Show } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { Hotkeys } from "#core/ui-next/components/hotkeys.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { usePopupContext } from "#core/ui-next/components/popup.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import {
	GameSetupOptionInfo,
	useGameSetupModelContext,
} from "#core/ui-next/screens/create-game/create-game-setup-model.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import style from "./map-select.scss?url";

export interface MapTypeButtonProps extends JSX.HTMLAttributes<HTMLDivElement> {
	name?: string;
	icon: string;
	onActivate?: () => void;
	description?: string;
	bgImage?: string;
	bgImagePositionX?: number;
	bgImagePositionY?: number;
}

// MARK: MAP TYPE BUTTON
export function MapTypeButton(props: MapTypeButtonProps) {
	return (
		<Activatable
			onActivate={props.onActivate}
			class={props.class ?? "create-game-map-select-box m-2 relative group"}
		>
			<Show when={!props.bgImage}>
				<div class="absolute inset-0 img-unit-panelbox pointer-events-none" />
			</Show>
			<Show when={props.bgImage}>
				<div class="absolute inset-0 overflow-hidden">
					<img
						src={props.bgImage}
						alt="Background"
						class="absolute"
						style={{
							left: (props.bgImagePositionX || 0) + "px",
							top: (props.bgImagePositionY || 0) + "px",
							width: Layout.pixels(1347),
							height: Layout.pixels(280),
						}}
					/>
				</div>
				<div class="create-game-setup-bottom-gradient absolute left-0 bottom-0" />
				<div class="absolute inset-0 w-full h-full border-2 border-secondary-3" />
			</Show>
			<div class="absolute inset-0 flex-auto flex flex-col justify-center items-center overflow-hidden">
				<Icon
					name={props.icon}
					isUrl={true}
					class={"create-game-map-select-icon mt-6"}
				/>
				<div class="flex-auto flex flex-col justify-start w-full items-center font-base text-center create-game-map-select-button-content">
					<div
						class="uppercase text-xl font-title font-black text-tertiary-1 flex flex-col justify-end font-fit-shrink max-w-84"
						style={{ "line-height": Layout.pixels(28), "min-height": Layout.pixels(56) }}
					>
						<L10n.Compose text={props.name!} />
					</div>
					<div class="map-select-divider-line" />
					<L10n.Stylize
						text={props.description!}
						class="font-body text-accent-2 text-sm"
					/>
				</div>
			</div>
			<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
		</Activatable>
	);
}

// MARK: MAP COMPONENT
const MapSelectComponent: Component = () => {
	const gameSetupModel = useGameSetupModelContext();
	const popupContext = usePopupContext();

	function handleSelection(option: GameSetupOptionInfo) {
		gameSetupModel.Map.setValue(option.value);
		popupContext.close("map-select");
	}

	return (
		<div class="img-frame-f1 relative h-full flex flex-row min-w-200 pointer-events-auto create-game-map-select">
			<Hotkeys
				hotkeys={[
					{ hotkeyAction: "accept", navTrayText: "LOC_GENERIC_SELECT" },
					{ hotkeyAction: "cancel", navTrayText: "LOC_GENERIC_BACK" },
				]}
			/>
			<div class="img-frame-filigree absolute top-4 left-4 size-64" />
			<div class="img-frame-filigree absolute top-4 right-4 size-64 -scale-x-100" />
			<CloseButton
				onActivate={() => popupContext.close("map-select")}
				class="absolute top-4 right-4"
			/>
			<div class="flex flex-col items-center justify-center ">
				<div class="flex flex-col items-center justify-center pt-7 mb-6">
					<div class="flex flex-row items-center justify-center -my-1\.5">
						<div class="leader-select-text font-title text-tertiary-1 font-black mx-7 uppercase">
							<L10n.Compose text="LOC_UI_CREATE_GAME_GAME_SETUP_MAP_TYPE" />
						</div>
					</div>
					<Filigree.Small />
				</div>

				<ScrollArea
					class="flex-auto create-game-map-select "
					reserveSpace={true}
				>
					<SpatialSlot
						name="map-options"
						class="flex flex-row flex-wrap items-center justify-center create-game-map-select"
					>
						<For each={gameSetupModel.Map.options}>
							{(option) => (
								<Tab.Trigger name="game-setup">
									<AudioContextProvider segment="MapSelectPopup">
										<MapTypeButton
											id="map-type"
											class="create-game-map-select-box img-unit-panelbox m-2 relative group"
											name={option.name}
											icon={option.icon}
											onActivate={() => handleSelection(option)}
											description={option.description}
										/>
									</AudioContextProvider>
								</Tab.Trigger>
							)}
						</For>
					</SpatialSlot>
				</ScrollArea>
			</div>
		</div>
	);
};

export const MapSelect = ComponentRegistry.register({
	name: "map-select",
	createInstance: MapSelectComponent,
	styles: [style],
});
